scwin.btn1_onclick = function(e) {
    grd1.setCellDisabled(0, "col2", true);
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 disabled버튼을 클릭하여 name2항목의 첫번째 값(test)을 더블클릭한다.
    //After running the sample file, click the disabled button and double-click the first value (test) of the name2 entry.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. text값이 textarea로 보여지고 영역은 disabled로 처리되어 보여진다.(이전에는 enable로 보여짐)
    //The text value is shown as textarea and the area is treated as disabled (previously shown as enable)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_grd1__col2').getValue() == 'test'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_grd1__col2').getDisabled()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
